// dashboard.mjs — weekly wait-time summary for the front desk. Spec: README.md.
import { readFileSync } from 'node:fs';

export function parse(text) {
  const [head, ...lines] = text.replace(/\r/g, '').trim().split('\n');
  const cols = head.split(',').map((c) => c.trim());
  return lines
    .filter((l) => l.trim())
    .map((l) => Object.fromEntries(l.split(',').map((v, i) => [cols[i], v.trim()])));
}

// Clinic-local wall-clock time, no zones: treat "YYYY-MM-DD HH:MM" as UTC so DST can't shift anything.
const stamp = (s) => Date.parse(s.replace(' ', 'T') + 'Z');
const minutes = (a, b) => (stamp(b) - stamp(a)) / 60000;

// Weeks start Monday.
export function weekOf(ts) {
  const d = new Date(ts.slice(0, 10) + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
  return d.toISOString().slice(0, 10);
}

export function median(xs) {
  const s = [...xs].sort((a, b) => a - b);
  const n = s.length;
  if (!n) return null;
  return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
}

export function summarize(rows) {
  const weeks = new Map();
  for (const r of rows) {
    const w = weekOf(r.signed_in);
    if (!weeks.has(w)) weeks.set(w, { visits: 0, waits: [] });
    const wk = weeks.get(w);
    wk.visits++;
    if (r.seen_at) wk.waits.push(minutes(r.signed_in, r.seen_at));
  }
  return [...weeks]
    .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
    .map(([week, { visits, waits }]) => ({
      week, visits, seen: waits.length, walkouts: visits - waits.length, median_wait_min: median(waits),
    }));
}

if (process.argv[2]) {
  for (const w of summarize(parse(readFileSync(process.argv[2], 'utf8')))) console.log(JSON.stringify(w));
}

