  // Someone with no shift in any earlier rota may simply be new; without `joined` they look owed all of it.
  for (const p of people) if (rotas.length && !p.joined && !rotas.some((r) => Object.values(r).some((on) => on.includes(p.name))))
    console.error(`rota: warning: ${p.name} has no shifts in the earlier rotas; if they joined since, set "joined" in the team file`);
  const ex = nurseExcess(people, start, Number(n));
  if (ex > 1e-9) console.error(`rota: warning: a nurse every day needs ${n} nurse shifts but the nurses' fair shares add to ${(Number(n) - ex).toFixed(2)}; they will come out at least ${ex.toFixed(2)} over between them, every period, and carry cannot repay it`);
  console.log(JSON.stringify(makeRota(people, start, Number(n), { carry })));
} catch (e) {
  console.error(`rota: ${e.message}`);
  process.exit(1);
}

