// assign.mjs — who works when, under POLICY.md.
//
// The old rule was "first nurse and first other person, alphabetically", so the top of the
// alphabet worked every day. Now each day goes to the pair furthest *behind their own pace*:
// a person's pace is their fair share (rule 4), spread over the days they are available, plus
// the same for weekend shifts on Saturdays and Sundays (rule 5). Names only break exact ties.
//
// Pacing alone can paint itself into a corner (rest days, leave, few nurses), so it is the
// ordering for a depth-first search with backtracking. The search prunes any branch where
// someone is already over share + tolerance, or can no longer reach share − tolerance on the
// days they have left. If the whole space is exhausted, no rota exists and we say so; if the
// search hits its budget first, we say that instead. Those are different facts.
import { days as daysOf, isWeekend } from './calendar.mjs';
import { shares, check, off, PER_DAY, MAX_RUN, TOL_TOTAL, TOL_WEEKEND } from './policy.mjs';

const EPS = 1e-9;

// Deterministic shuffle (FNV-1a seed, mulberry32 stream, Fisher-Yates).
export function shuffle(xs, key) {
  let h = 2166136261;
  for (const c of key) h = Math.imul(h ^ c.charCodeAt(0), 16777619) >>> 0;
  const rnd = () => {
    h = (h + 0x6d2b79f5) >>> 0;
    let t = Math.imul(h ^ (h >>> 15), 1 | h);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  for (let i = xs.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); [xs[i], xs[j]] = [xs[j], xs[i]]; }
  return xs;
}

export function makeRota(people, start, n, { budget = 200000, carry = null } = {}) {
  if (!Number.isInteger(n) || n < 1) throw new Error(`period must be a positive whole number of days, got ${n}`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(start) || Number.isNaN(Date.parse(`${start}T00:00:00Z`)))
    throw new Error(`bad start date: ${start}`);
  const names = people.map((p) => p.name);
  if (new Set(names).size !== names.length) throw new Error('names must be unique');
  for (const p of people) if (!(p.fte >= 0)) throw new Error(`bad fte for ${p.name}`);

  const ds = daysOf(start, n);
  // Ties are broken by position in this list. Sorting by name alone hands every leftover shift
  // to the top of the alphabet, period after period: on a weekly rota for seven equal people,
  // Ana ended a year 52 shifts over share and Yusuf 52 under, while every week passed POLICY.md.
  // Rotating the order one place per period only cut that to +15/-14, because who wins also
  // depends on where the nurses sit. So the order is shuffled, seeded by the period's start and
  // length: deterministic, independent of input order, and no name has a standing advantage.
  const team = shuffle([...people].sort((a, b) => a.name.localeCompare(b.name)), `${start}/${n}`);
  const k = team.length;
  const sh = shares(team, start, n);
  const share = team.map((p) => sh.get(p.name));

  // Cheap impossibility checks, with a reason a manager can act on.
  for (const d of ds) {
    const free = team.filter((p) => !off(p, d) && p.fte > 0);
    if (!free.some((p) => p.role === 'nurse')) throw new Error(`no nurse available on ${d}`);
    if (free.length < PER_DAY) throw new Error(`fewer than ${PER_DAY} people available on ${d}`);
  }

  // avail[i][j]: is person j free (not on leave, fte > 0) on day i.
  const avail = ds.map((d) => team.map((p) => !off(p, d) && p.fte > 0));
  const wk = ds.map(isWeekend);
  // remaining available days / weekend days from day i on (index n = 0).
  const remA = Array.from({ length: n + 1 }, () => new Array(k).fill(0));
  const remW = Array.from({ length: n + 1 }, () => new Array(k).fill(0));
  for (let i = n - 1; i >= 0; i--) for (let j = 0; j < k; j++) {
    remA[i][j] = remA[i + 1][j] + (avail[i][j] ? 1 : 0);
    remW[i][j] = remW[i + 1][j] + (avail[i][j] && wk[i] ? 1 : 0);
  }
  // cap[i][j][r]: most shifts j can still work from day i on, if they have worked r days in a
  // row going in (rule 3 exact). capW: the same counting only weekend shifts.
  const mk = (count) => {
    const f = Array.from({ length: n + 1 }, () => Array.from({ length: k }, () => new Array(MAX_RUN + 1).fill(0)));
    for (let i = n - 1; i >= 0; i--) for (let j = 0; j < k; j++) for (let r = 0; r <= MAX_RUN; r++) {
      const off = f[i + 1][j][0];
      const on = avail[i][j] && r < MAX_RUN ? count(i) + f[i + 1][j][r + 1] : -1;
      f[i][j][r] = Math.max(off, on);
    }
    return f;
  };
  const cap = mk(() => 1), capW = mk((i) => (wk[i] ? 1 : 0));
  const nurses = team.map((p, j) => j).filter((j) => team[j].role === 'nurse');

  // The policy can contradict itself: rule 4 shares by fte, not role, but rule 1 needs a nurse
  // every day. If the nurses' shares (plus tolerance) can't cover every day, no rota exists.
  // Shifts are whole: the most anyone may work is floor(share + tolerance).
  const most = team.map((p, j) => Math.floor(share[j].total + TOL_TOTAL + EPS));
  const nurseRoom = nurses.reduce((a, j) => a + Math.min(most[j], cap[0][j][0]), 0);
  if (nurseRoom < n - EPS) throw new Error(
    `no rota satisfies POLICY.md: ${n} days need a nurse each, but within fair share + ${TOL_TOTAL}, leave and rest the nurses can cover at most ${nurseRoom}`);
  const teamRoom = team.reduce((a, p, j) => a + Math.min(most[j], cap[0][j][0]), 0);
  if (teamRoom < PER_DAY * n) throw new Error(
    `no rota satisfies POLICY.md: ${n} days need ${PER_DAY * n} shifts, but within fair share + ${TOL_TOTAL}, leave and rest the team can cover at most ${teamRoom}`);
  for (let j = 0; j < k; j++) if (cap[0][j][0] < share[j].total - TOL_TOTAL - EPS) throw new Error(
    `no rota satisfies POLICY.md: ${team[j].name} can work at most ${cap[0][j][0]} shifts (leave and rest) but fair share needs ${Math.ceil(share[j].total - TOL_TOTAL - EPS)}`);

  // Memory. Every period is judged alone (POLICY.md), so a memoryless rota rounds each person
  // up or down at random and the errors random-walk: on weekly rotas a part-timer ended a year
  // 20 weekend shifts behind with every week passing. With `carry` (balances from earlier rotas,
  // policy.balance) each person aims at share − balance instead of share, held inside the
  // tolerance band so the target itself always satisfies rules 4 and 5. The pruning below still
  // uses the plain shares: carry steers the search, it never loosens the policy.
  // Balances are scaled down together (not clipped one by one) when the largest exceeds the
  // band. Clipping each person separately loses who is owed *most* once several are past the
  // limit, which happens when the policy itself forces a drift (see README: nurse squeeze).
  const aim = (key, tol) => {
    const b = team.map((p) => carry?.get(p.name)?.[key] ?? 0);
    const big = Math.max(0, ...b.map(Math.abs)), lim = tol - 0.5;
    const f = big > lim ? lim / big : 1;
    const raw = team.map((p, j) => share[j][key] - b[j] * f);
    const fix = (team.reduce((a, p, j) => a + share[j][key], 0) - raw.reduce((a, b) => a + b, 0)) / Math.max(1, k);
    return raw.map((x) => x + fix);   // targets still add up to the period's shifts
  };
  const tgt = aim('total', TOL_TOTAL), tgtW = aim('weekend', TOL_WEEKEND);

  // Pace: where each person "should" be after day i, proportional to availability used so far.
  const totA = remA[0], totW = remW[0];
  const pace = (j, i) => (totA[j] ? tgt[j] * (totA[j] - remA[i + 1][j]) / totA[j] : 0);
  const paceW = (j, i) => (totW[j] ? tgtW[j] * (totW[j] - remW[i + 1][j]) / totW[j] : 0);

  const total = new Array(k).fill(0), wknd = new Array(k).fill(0), run = new Array(k).fill(0);
  const chosen = new Array(n);
  let nodes = 0, gaveUp = false;

  const viable = (i) => {   // state after day i is assigned
    for (let j = 0; j < k; j++) {
      if (total[j] > share[j].total + TOL_TOTAL + EPS) return false;
      if (wknd[j] > share[j].weekend + TOL_WEEKEND + EPS) return false;
      if (total[j] + cap[i + 1][j][run[j]] < share[j].total - TOL_TOTAL - EPS) return false;
      if (wknd[j] + capW[i + 1][j][run[j]] < share[j].weekend - TOL_WEEKEND - EPS) return false;
    }
    // Every remaining day needs a nurse: do the nurses have that much room left between them?
    let room = 0;
    for (const j of nurses) room += Math.min(most[j] - total[j], cap[i + 1][j][run[j]]);
    return room >= n - 1 - i - EPS;
  };

  const candidates = (i) => {
    const free = [];
    for (let j = 0; j < k; j++) if (avail[i][j] && run[j] < MAX_RUN) free.push(j);
    const need = (j) => (pace(j, i) - total[j]) + (wk[i] ? 2 * (paceW(j, i) - wknd[j]) : 0);
    const out = [];
    for (let a = 0; a < free.length; a++) for (let b = a + 1; b < free.length; b++) {
      const x = free[a], y = free[b];
      if (team[x].role !== 'nurse' && team[y].role !== 'nurse') continue;
      // Prefer those most behind; among equals, those who have been on longest get the day off.
      out.push({ x, y, s: need(x) + need(y) - 0.01 * (run[x] + run[y]) });
    }
    return out.sort((p, q) => q.s - p.s || p.x - q.x || p.y - q.y);
  };

  const dfs = (i) => {
    if (i === n) return true;
    for (const { x, y } of candidates(i)) {
      if (++nodes > budget) { gaveUp = true; return false; }
      const saved = run.slice();
      for (let j = 0; j < k; j++) run[j] = j === x || j === y ? run[j] + 1 : 0;
      total[x]++; total[y]++;
      if (wk[i]) { wknd[x]++; wknd[y]++; }
      chosen[i] = [x, y];
      if (viable(i) && dfs(i + 1)) return true;
      total[x]--; total[y]--;
      if (wk[i]) { wknd[x]--; wknd[y]--; }
      for (let j = 0; j < k; j++) run[j] = saved[j];
      if (gaveUp) return false;
    }
    return false;
  };

  const found = dfs(0);
  if (!found) {
    throw new Error(gaveUp
      ? `no rota found within the search budget (${budget} steps); the policy may still be satisfiable`
      : 'no rota satisfies POLICY.md for this team and period (cover, leave, rest and fair-share rules conflict)');
  }

  const rota = {};
  ds.forEach((d, i) => {
    const [x, y] = chosen[i];
    // Nurse first, as the old output did.
    rota[d] = team[x].role === 'nurse' || team[y].role !== 'nurse' ? [team[x].name, team[y].name] : [team[y].name, team[x].name];
  });
  const v = check(team, start, n, rota);
  if (v.length) throw new Error(`internal error, rota breaks policy: ${v[0]}`);
  return rota;
}

