// people.mjs — load and validate the team file.
import { readFileSync } from 'node:fs';

export function loadPeople(path) {
  const people = JSON.parse(readFileSync(path, 'utf8'));
  for (const p of people) {
    if (!p.name || !['nurse', 'aide'].includes(p.role)) throw new Error(`bad person: ${JSON.stringify(p)}`);
    p.fte = Number(p.fte ?? 1);
    // A leave date the calendar can't match would be silently ignored, and the person rostered.
    for (const d of p.leave || []) if (!okDate(d))
      throw new Error(`bad leave date for ${p.name}: ${JSON.stringify(d)} (want YYYY-MM-DD)`);
    p.leave = new Set(p.leave || []);
    // Optional time on the team (inclusive). Without `joined`, a new person looks owed every shift
    // of every old rota passed as carry, and is pinned at share + 2 for years.
    for (const k of ['joined', 'left']) if (p[k] != null && !okDate(p[k])) throw new Error(`bad ${k} date for ${p.name}: ${JSON.stringify(p[k])} (want YYYY-MM-DD)`);
    if (p.joined && p.left && p.left < p.joined) throw new Error(`${p.name} left before joining`);
  }
  return people;
}

function okDate(d) {
  return typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d) && !Number.isNaN(Date.parse(`${d}T00:00:00Z`))
    && new Date(`${d}T00:00:00Z`).toISOString().slice(0, 10) === d;   // month 13 is NaN; Feb 30 rolls over
}

