const wkd = (d) => [0, 6].includes(new Date(`${d}T00:00:00Z`).getUTCDay());
const people = pf ? JSON.parse(readFileSync(pf, 'utf8'))
  : [...new Set(Object.values(rota).flat())].map((name) => ({ name }));
