        if (l >= n) break;
        const r = l + 1;
        const c = r < n && Heap.less(a[r], a[l]) ? r : l;
        if (!Heap.less(a[c], last)) break;
        a[i] = a[c]; i = c;
      }
      a[i] = last;
    }
    return top;
  }
