  for (let c = 0; c < 300; c++) {
    const model = tieModel(c);
    const injections = [];
    for (let i = 0, k = 1 + r(4); i < k; i++) injections.push({ at: r(7), name: 'x', value: i });
    const scale = [1, 7, 0.25][c % 3];
