  // A, B, C are each someone's parent, so none is a leaf; T is a leaf.
  const list = [R('A', { parent: 'C' }), R('B', { parent: 'A' }), R('C', { parent: 'B' }), R('T', { parent: 'A' }), R('S', { parent: 'S' })];
  assert.deepEqual(codes(list), ['A:cycle', 'B:cycle', 'C:cycle', 'S:cycle']);
